import sys

MOD = 10**9 + 7

def count_digits(n):
    if n == 0:
        return 1
    count = 0
    while n > 0:
        count += 1
        n = n // 10
    return count

def compute_sum(L, R):
    total = 0
    for num in range(L, R + 1):
        digits = count_digits(num)
        total = (total + num * digits) % MOD
    return total

def main():
    T = int(sys.stdin.readline())
    for _ in range(T):
        L, R = map(int, sys.stdin.readline().split())
        print(compute_sum(L, R))

if __name__ == "__main__":
    main()
